<script setup>import{ref}from'vue';import{ElMessage}from'element-plus';import PageHeader from'../components/PageHeader.vue';const active=ref('超级管理员'),checked=ref(['需求查看','需求分派','订单查看','方案审核','生产更新']);const roles=['超级管理员','设计师','生产主管'];const tree=[{label:'业务管理',children:[{label:'需求查看'},{label:'需求分派'},{label:'订单查看'},{label:'方案审核'}]},{label:'生产管理',children:[{label:'生产更新'}]},{label:'系统管理',children:[{label:'用户管理'},{label:'角色配置'},{label:'系统设置'}]}];function save(){ElMessage.success('角色权限已保存')}</script><template><div class="admin-page"><PageHeader title="角色权限" description="配置不同岗位可访问的菜单与业务操作"><el-button type="primary" @click="save">保存权限</el-button></PageHeader><div class="role-layout work-surface"><aside><div class="role-head">角色列表 <el-button link type="primary">新增</el-button></div><button v-for="x in roles" :key="x" :class="{active:active===x}" @click="active=x">{{x}}</button></aside><main><h2>{{active}}</h2><p>勾选该角色允许访问的菜单和操作权限。</p><el-tree :data="tree" show-checkbox node-key="label" :default-checked-keys="checked" default-expand-all/></main></div></div></template><style scoped>.role-layout{display:grid;grid-template-columns:240px 1fr;min-height:520px}.role-layout aside{border-right:1px solid var(--border);padding:14px}.role-head{display:flex;justify-content:space-between;padding:8px 10px 14px;font-weight:600}.role-layout aside button{display:block;width:100%;padding:11px 12px;border:0;background:none;text-align:left;cursor:pointer}.role-layout aside button.active{background:#efe7df;color:var(--primary)}.role-layout main{padding:28px 34px}.role-layout main h2{font:500 22px var(--display);margin:0}.role-layout main p{color:var(--muted);margin-bottom:24px}@media(max-width:600px){.role-layout{grid-template-columns:1fr}.role-layout aside{border-right:0;border-bottom:1px solid var(--border)}}</style>
